export type I18nText = {
    zh_cn: string;
    en_us?: string;
    ja_jp?: string;
};
export type DepartmentBasic = {
    departmentID: string;
    name: I18nText;
    /** 飞书部门 open id（od- 开头），调飞书部门能力时使用 */
    openDepartmentID?: string;
};
/** 直属上级 / 虚线上级，仅在 needFullFields 时返回 */
export type LeaderUser = {
    /** 飞书企业内 user_id */
    employeeID?: string;
    /** 妙搭用户全局唯一 ID */
    miaodaUserID?: string;
};
export type UserInfo = {
    userID: string;
    larkUserID: string;
    name: I18nText;
    avatar: string;
    userType: '_employee' | '_externalUser' | '_anonymousUser';
    department: DepartmentBasic;
    email?: string;
    tenantName?: string;
    /** 妙搭用户全局唯一 ID（来源同 userID，向前兼容别名） */
    miaodaUserID?: string;
    /** 飞书企业内 user_id，仅内部飞书用户；调飞书开放平台能力时使用 */
    employeeID?: string;
    /** 飞书用户全局唯一 ID（来源同 larkUserID 别名） */
    larkID?: string;
    /** 昵称（多语言），仅 needFullFields=true 时返回 */
    nickname?: I18nText;
    /** 手机号，仅 needFullFields=true 时返回 */
    mobile?: string;
    /** 性别，仅 needFullFields=true 时返回 */
    gender?: string;
    /** 国家/地区，仅 needFullFields=true 时返回 */
    country?: string;
    /** 工位，仅 needFullFields=true 时返回 */
    workStation?: string;
    /** 工号，仅 needFullFields=true 时返回 */
    employeeNo?: string;
    /** 城市，仅 needFullFields=true 时返回 */
    city?: string;
    /** 职位（多语言），仅 needFullFields=true 时返回 */
    jobTitle?: I18nText;
    /** 员工类型，仅 needFullFields=true 时返回 */
    employeeType?: string;
    /** 直属上级，仅 needFullFields=true 时返回 */
    leader?: LeaderUser;
    /** 虚线上级，仅 needFullFields=true 时返回 */
    dottedLineLeaders?: LeaderUser[];
};
export type DepartmentInfo = {
    departmentID: string;
    larkDepartmentID: string;
    name: I18nText;
    /** 飞书部门 open id（od- 开头） */
    openDepartmentID?: string;
};
export type AccountType = 'apaas' | 'lark';
export type SearchAvatar = {
    avatar: {
        image: {
            large: string;
        };
    };
};
export type SearchUsersParams = {
    query?: string;
    offset?: number;
    pageSize?: number;
    searchExternalContact?: boolean;
    /** 是否返回 full 字段（手机号/职位/上级等），默认 false */
    needFullFields?: boolean;
};
export type SearchUsersResponse = {
    data: {
        userList: UserInfo[];
        total: number;
    };
    status_code: string;
};
export type ConvertExternalContactResponse = {
    data: {
        userInfo: {
            tenantID: number;
            userID: number;
        };
    };
};
export type BatchGetUsersResponse = {
    data: {
        userInfoMap: Record<string, UserInfo & SearchAvatar>;
        baseResp?: {
            statusCode?: number;
            statusMessage?: string;
        };
    };
};
export type SearchDepartmentsParams = {
    query?: string;
    offset?: number;
    pageSize?: number;
};
export type SearchDepartmentsResponse = {
    data: {
        departmentList: DepartmentInfo[];
        total: number;
    };
    status_code: string;
};
export type ChatInfo = {
    /** 群组 ID */
    chatID: string;
    /** 飞书群组 open id（oc_ 开头），调飞书群组能力时使用 */
    openChatID?: string;
    /** 群组名称（国际化文本） */
    name: I18nText;
    /** 头像：URL 或 16 进制 RGB 颜色 */
    avatar: string;
    /** 是否是外部群 */
    isExternal?: boolean;
    /** 群成员数量（不包括机器人），搜索接口返回，批量查询接口不返回 */
    userCount?: number;
};
export type SearchChatsParams = {
    query?: string;
    offset?: number;
    pageSize?: number;
};
export type SearchChatsResponse = {
    data: {
        result: {
            chatResult?: {
                total: number;
                items: ChatInfo[];
            };
        };
    };
    status_code: string;
};
export type BatchGetChatsResponse = {
    data: {
        chatInfoMap: Record<string, ChatInfo>;
    };
    status_code: string;
};
export type UserProfileAccountStatus = 0 | 1 | 2 | 3 | 4;
export type SimpleUserProfileInfo = {
    name?: string;
    avatar?: string;
    email?: string;
    userStatus: UserProfileAccountStatus;
    userType: '_employee' | '_externalUser';
};
export type LarkCardParam = {
    needRedirect?: boolean;
    redirectURL?: string;
    larkAppID: string;
    jsAPITicket: string;
    larkOpenID: string;
    targetLarkOpenID: string;
};
export type SimpleUserProfileData = {
    useLarkCard: false;
    userProfileInfo: SimpleUserProfileInfo;
};
export type OfficialUserProfileData = {
    useLarkCard: true;
    larkCardParam: LarkCardParam;
};
export type UserProfileData = SimpleUserProfileData | OfficialUserProfileData;
export type UserProfileResponse = {
    data: UserProfileData;
};
